#!/bin/bash
set -uo pipefail
umask 077
mkdir -p /opt/next-submission-preflight /var/lib/next-preflight
exec > >(tee -a /var/log/next-preflight.log /dev/ttyS0) 2>&1
echo NEXT_PREFLIGHT_BOOT_STARTED
printf '%s' '' | base64 -d > /opt/next-submission-preflight/main.py
printf '%s' '' | base64 -d > /opt/next-submission-preflight/upload.py
if [ -x /opt/conda/bin/python ]; then
  PYTHON_BIN=/opt/conda/bin/python
else
  PYTHON_BIN=$(command -v python3)
fi
"$PYTHON_BIN" -m pip install --disable-pip-version-check --no-input trl==1.8.0 transformers==5.13.1 jinja2==3.1.6 datasets==4.8.5 peft==0.19.1 torchao==0.17.0 wandb==0.28.0
INSTALL_EXIT=$?
if [ "$INSTALL_EXIT" -eq 0 ]; then
  "$PYTHON_BIN" -m pip uninstall --yes torchaudio torchvision
  OPTIONAL_CLEANUP_EXIT=$?
else
  OPTIONAL_CLEANUP_EXIT=$INSTALL_EXIT
fi
if [ "$INSTALL_EXIT" -eq 0 ] && [ "$OPTIONAL_CLEANUP_EXIT" -eq 0 ]; then
  "$PYTHON_BIN" /opt/next-submission-preflight/main.py
  RUN_EXIT=$?
else
  RUN_EXIT=$OPTIONAL_CLEANUP_EXIT
fi
echo NEXT_PREFLIGHT_EXIT_CODE=$RUN_EXIT
"$PYTHON_BIN" /opt/next-submission-preflight/upload.py   /var/log/next-preflight.log /var/lib/next-preflight/result.json
UPLOAD_EXIT=$?
echo NEXT_PREFLIGHT_UPLOAD_EXIT_CODE=$UPLOAD_EXIT
sync
sleep 10
shutdown -h now
exit "$RUN_EXIT"
